  async function renderClientConsult(message='',isError=false){const h=openClientHost();if(!h)return;h.innerHTML='<div class="ppc-loading"><span></span><strong>Carregando clientes...</strong></div>';try{await loadClientData();const active=clientData.clients.filter(c=>statusKind(c?.status)==='active').length,blocked=clientData.clients.filter(c=>statusKind(c?.status)==='blocked').length,pppoe=clientData.clients.filter(c=>norm(c?.connection_type)==='pppoe').length;h.innerHTML=`<div class="ppc-head"><div><span class="ppc-eyebrow">CLIENTE · CONSULTA</span><h1>Consultar clientes</h1><p>Busca rápida da base de assinantes, contrato, plano e conexão.</p></div><div class="ppc-head-actions"><button type="button" class="ppc-button" id="ppc-refresh">↻ Atualizar</button><button type="button" class="ppc-button primary" id="ppc-go-create">＋ Cadastrar cliente</button></div></div>${message?`<div class="ppc-message ${isError?'error':''}">${esc(message)}</div>`:''}<div class="ppc-summary"><article><small>TOTAL DA BASE</small><strong>${integer(clientData.clients.length)}</strong></article><article><small>ATIVOS</small><strong>${integer(active)}</strong></article><article><small>BLOQUEADOS</small><strong>${integer(blocked)}</strong></article><article><small>COM PPPoE</small><strong>${integer(pppoe)}</strong></article></div><section class="ppc-panel"><div class="ppc-toolbar"><label class="ppc-search">⌕<input id="ppc-search" placeholder="Nome, CPF/CNPJ, contrato, telefone ou PPPoE"></label><select id="ppc-filter"><option value="all">Todos os status</option><option value="active">Ativos</option><option value="blocked">Bloqueados</option><option value="overdue">Em atraso</option></select><button type="button" class="ppc-button primary" id="ppc-search-button">Consultar</button></div><div class="ppc-table-wrap"><table class="ppc-table"><thead><tr><th>CLIENTE</th><th>DOCUMENTO / CONTATO</th><th>PLANO</th><th>VENC.</th><th>CONEXÃO</th><th>STATUS</th><th>AÇÃO</th></tr></thead><tbody id="ppc-client-rows"></tbody></table></div><div class="ppc-result-info" id="ppc-result-info"></div></section>`;h.querySelector('#ppc-go-create').onclick=()=>renderClientCreate();h.querySelector('#ppc-refresh').onclick=()=>renderClientConsult();h.querySelector('#ppc-search-button').onclick=drawClientRows;h.querySelector('#ppc-search').addEventListener('input',drawClientRows);h.querySelector('#ppc-filter').addEventListener('change',drawClientRows);drawClientRows()}catch(e){h.innerHTML=`<div class="ppc-message error">${esc(e?.message||e)}</div>`}}
  async function loadProfiles(routerId,select){if(!select)return;select.innerHTML='<option value="">Carregando profiles...</option>';select.disabled=true;try{const r=await api()?.mikrotik?.profiles?.(Number(routerId)),items=[...new Set((r?.profiles||[]).map(x=>String(x?.name||'').trim()).filter(Boolean))];select.innerHTML='<option value="">Selecione o profile</option>'+items.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(items.includes('default'))select.value='default';else if(items.length===1)select.value=items[0]}catch(e){select.innerHTML=`<option value="">${esc(e?.message||'Profiles indisponíveis')}</option>`}finally{select.disabled=false}}
  function toggleConnectionFields(form){const enabled=form?.elements?.connection_type?.value==='PPPoE';for(const name of ['router_id','pppoe_username','pppoe_password','mikrotik_profile','ip','mac_address']){const el=form?.elements?.[name];if(el)el.disabled=!enabled}if(form?.elements?.router_id)form.elements.router_id.required=enabled;if(form?.elements?.pppoe_username)form.elements.pppoe_username.required=enabled;if(form?.elements?.pppoe_password)form.elements.pppoe_password.required=enabled;if(form?.elements?.mikrotik_profile)form.elements.mikrotik_profile.required=enabled}
